    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 21) NOT NULL,
    "COMMENT" CHARACTER VARYING(1000),
    "NAME" CHARACTER VARYING(255),
    "PHONE" CHARACTER VARYING(255),
    "RATING" INTEGER,
    "TEACHER_ID" BIGINT
);         
